use crate::sha256::sha256_hex;
use std::collections::BTreeMap;

#[derive(Clone, Debug, PartialEq)]
pub struct ProcessScanRow { pub pid: u32, pub ppid: u32, pub name: String, pub cpu_time_ms_cumulative: f64, pub memory_mb: f64 }
#[derive(Clone, Debug, PartialEq)]
pub struct ProcessMetricsRow { pub pid: u32, pub ppid: u32, pub name: String, pub name_hash: String, pub cpu_time_ms_sample: f64, pub sample_avg_mem_mb: f64, pub sample_peak_mem_mb: f64, pub session_peak_mem_mb: f64, pub memory_during_peak_mb: f64, pub cpu_during_peak_pct: f64 }
#[derive(Clone, Debug, PartialEq)]
pub struct ProcessMetricsSample { pub sample_start_ms: u64, pub sample_end_ms: u64, pub num_subsamples: u32, pub sample_seqno: u64, pub session_id: String, pub rows: Vec<ProcessMetricsRow> }
#[derive(Clone, Debug)]
struct Tracker { ppid:u32,name:String,cpu_baseline_ms:Option<f64>,cpu_last_ms:Option<f64>,mem_sum_mb:f64,mem_count:u32,mem_peak_mb:f64,session_peak_mem_mb:f64,last_seen_generation:u64,last_sample_time_ms:Option<u64>,last_cpu_ms_for_util:Option<f64>,latest_mem_mb:f64,latest_cpu_util_pct:f64,memory_at_sample_peak_mb:f64,cpu_util_at_sample_peak_pct:f64 }

pub struct ProcessMetricsSampler { session_id:String,trackers:BTreeMap<u32,Tracker>,sample_seqno:u64,window_start_ms:Option<u64>,window_last_seen_ms:u64,window_subsample_count:u32,window_generation:u64,sample_peak_total_mem_mb:f64,sample_peak_total_cpu_pct:f64 }
impl ProcessMetricsSampler {
 pub fn new(session_id:impl Into<String>)->Self{Self{session_id:session_id.into(),trackers:BTreeMap::new(),sample_seqno:0,window_start_ms:None,window_last_seen_ms:0,window_subsample_count:0,window_generation:0,sample_peak_total_mem_mb:-1.0,sample_peak_total_cpu_pct:-1.0}}
 pub fn record_subsample(&mut self,now_ms:u64,rows:&[ProcessScanRow]){if rows.is_empty(){return}self.window_start_ms.get_or_insert(now_ms);self.window_last_seen_ms=now_ms;self.window_subsample_count=self.window_subsample_count.saturating_add(1);let(mut total_mem,mut total_cpu)=(0.0,0.0);let mut seen=Vec::with_capacity(rows.len());for row in rows{if !row.cpu_time_ms_cumulative.is_finite()||!row.memory_mb.is_finite(){continue}let generation=self.window_generation;let t=self.trackers.entry(row.pid).or_insert_with(||Tracker{ppid:row.ppid,name:row.name.clone(),cpu_baseline_ms:None,cpu_last_ms:None,mem_sum_mb:0.0,mem_count:0,mem_peak_mb:0.0,session_peak_mem_mb:row.memory_mb.max(0.0),last_seen_generation:generation,last_sample_time_ms:None,last_cpu_ms_for_util:None,latest_mem_mb:row.memory_mb.max(0.0),latest_cpu_util_pct:0.0,memory_at_sample_peak_mb:0.0,cpu_util_at_sample_peak_pct:0.0});t.ppid=row.ppid;t.name=row.name.clone();t.last_seen_generation=self.window_generation;t.latest_mem_mb=row.memory_mb.max(0.0);t.session_peak_mem_mb=t.session_peak_mem_mb.max(t.latest_mem_mb);t.cpu_baseline_ms.get_or_insert(row.cpu_time_ms_cumulative.max(0.0));t.cpu_last_ms=Some(row.cpu_time_ms_cumulative.max(0.0));t.mem_sum_mb+=t.latest_mem_mb;t.mem_count=t.mem_count.saturating_add(1);t.mem_peak_mb=t.mem_peak_mb.max(t.latest_mem_mb);let cpu=match(t.last_sample_time_ms,t.last_cpu_ms_for_util){(Some(last_at),Some(last_cpu)) if now_ms>last_at=>((row.cpu_time_ms_cumulative-last_cpu).max(0.0)/(now_ms-last_at)as f64)*100.0,_=>0.0};t.latest_cpu_util_pct=cpu;t.last_sample_time_ms=Some(now_ms);t.last_cpu_ms_for_util=Some(row.cpu_time_ms_cumulative.max(0.0));total_mem+=t.latest_mem_mb;total_cpu+=cpu;seen.push(row.pid)}if total_mem>self.sample_peak_total_mem_mb{self.sample_peak_total_mem_mb=total_mem;for t in self.trackers.values_mut(){t.memory_at_sample_peak_mb=0.0}for pid in &seen{if let Some(t)=self.trackers.get_mut(pid){t.memory_at_sample_peak_mb=t.latest_mem_mb}}}if total_cpu>self.sample_peak_total_cpu_pct{self.sample_peak_total_cpu_pct=total_cpu;for t in self.trackers.values_mut(){t.cpu_util_at_sample_peak_pct=0.0}for pid in &seen{if let Some(t)=self.trackers.get_mut(pid){t.cpu_util_at_sample_peak_pct=t.latest_cpu_util_pct}}}}
 pub fn create_sample(&mut self)->Option<ProcessMetricsSample>{if self.window_subsample_count==0{return None}let start=self.window_start_ms.unwrap_or(self.window_last_seen_ms);let end=self.window_last_seen_ms;let count=self.window_subsample_count;let mut rows=Vec::new();for(&pid,t)in&self.trackers{if t.mem_count==0{continue}let(Some(base),Some(last))=(t.cpu_baseline_ms,t.cpu_last_ms)else{continue};let(name,name_hash)=sanitize_process_name(&t.name);rows.push(ProcessMetricsRow{pid,ppid:t.ppid,name,name_hash,cpu_time_ms_sample:(last-base).max(0.0),sample_avg_mem_mb:t.mem_sum_mb/t.mem_count as f64,sample_peak_mem_mb:t.mem_peak_mb,session_peak_mem_mb:t.session_peak_mem_mb,memory_during_peak_mb:t.memory_at_sample_peak_mb,cpu_during_peak_pct:t.cpu_util_at_sample_peak_pct})}let sample=ProcessMetricsSample{sample_start_ms:start,sample_end_ms:end,num_subsamples:count,sample_seqno:self.sample_seqno,session_id:self.session_id.clone(),rows};self.sample_seqno=self.sample_seqno.saturating_add(1);self.window_start_ms=Some(end);self.window_last_seen_ms=0;self.window_subsample_count=0;for t in self.trackers.values_mut(){if let Some(last)=t.cpu_last_ms{t.cpu_baseline_ms=Some(last)}t.mem_sum_mb=0.0;t.mem_count=0;t.mem_peak_mb=0.0;t.memory_at_sample_peak_mb=0.0;t.cpu_util_at_sample_peak_pct=0.0}self.sample_peak_total_mem_mb=-1.0;self.sample_peak_total_cpu_pct=-1.0;let g=self.window_generation;self.trackers.retain(|_,t|t.last_seen_generation==g);self.window_generation=self.window_generation.saturating_add(1);Some(sample)}
 pub fn reset(&mut self){self.trackers.clear();self.sample_seqno=0;self.window_start_ms=None;self.window_last_seen_ms=0;self.window_subsample_count=0;self.window_generation=0;self.sample_peak_total_mem_mb=-1.0;self.sample_peak_total_cpu_pct=-1.0}
}
pub fn sanitize_process_name(raw:&str)->(String,String){let hash=sha256_hex(raw.as_bytes());let base=raw.rsplit(|c|c=='/'||c=='\\').next().unwrap_or(raw).trim();if is_helper(base){return(base.to_string(),hash)}(base.split_whitespace().next().unwrap_or_default().to_string(),hash)}
fn is_helper(v:&str)->bool{let Some(rest)=v.strip_prefix("Fabushi Helper").or_else(||v.strip_prefix("Fabushi Lab Helper")).or_else(||v.strip_prefix("Grok Bot Helper")).or_else(||v.strip_prefix("Grok Bot Lab Helper"))else{return false};rest.is_empty()||matches!(rest," (GPU)"|" (Plugin)"|" (Renderer)")}
#[cfg(test)]mod tests{use super::*;fn r(pid:u32,name:&str,cpu:f64,mem:f64)->ProcessScanRow{ProcessScanRow{pid,ppid:1,name:name.into(),cpu_time_ms_cumulative:cpu,memory_mb:mem}}#[test]fn window_and_peak_semantics(){let mut s=ProcessMetricsSampler::new("s");s.record_subsample(1000,&[r(10,"/x/Fabushi Helper (Renderer)",100.0,50.0)]);s.record_subsample(2000,&[r(10,"/x/Fabushi Helper (Renderer)",350.0,80.0)]);let x=s.create_sample().unwrap();assert_eq!((x.sample_start_ms,x.sample_end_ms,x.num_subsamples),(1000,2000,2));assert_eq!(x.rows[0].cpu_time_ms_sample,250.0);assert_eq!(x.rows[0].sample_avg_mem_mb,65.0);assert_eq!(x.rows[0].cpu_during_peak_pct,25.0);assert_eq!(x.rows[0].name,"Fabushi Helper (Renderer)");assert_eq!(x.rows[0].name_hash.len(),64)}#[test]fn redacts_arbitrary_paths(){let(name,hash)=sanitize_process_name("/private/user/secret-tool --token abc");assert_eq!(name,"secret-tool");assert_eq!(hash.len(),64);assert!(!hash.contains("secret"))}#[test]fn reset_does_not_fabricate(){let mut s=ProcessMetricsSampler::new("s");assert!(s.create_sample().is_none());s.record_subsample(1,&[r(1,"p",1.0,2.0)]);assert!(s.create_sample().is_some());s.reset();assert!(s.create_sample().is_none())}}
